import {createApi} from './client.mjs';const api=createApi(window.PLANTO_CONFIG?.apiUrl||'');const token=location.hash.slice(1),root=document.querySelector('#tracking');
async function update(){try{const r=await api.request('/v1/shared/'+encodeURIComponent(token));root.replaceChildren();for(const t of [r.origin+' → '+r.destination,r.vehicle+' · '+r.plate,'Trip: '+r.status]){const p=document.createElement('p');p.textContent=t;root.append(p);}if(r.location){const a=document.createElement('a');a.href=`https://www.google.com/maps?q=${r.location.lat},${r.location.lng}`;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Open driver location · updated '+new Date(r.location.updated_at*1000).toLocaleTimeString();root.append(a);}else{const p=document.createElement('p');p.textContent='No recent driver location available.';root.append(p);}}catch(e){root.textContent=e.message;}}
void update();setInterval(()=>{if(!document.hidden)void update();},15000);
